/* eslint-disable @typescript-eslint/no-require-imports */
const { createHash, randomUUID } = require("node:crypto");
const { readFileSync } = require("node:fs");
const { join } = require("node:path");

const {
  DynamoDBClient,
  GetItemCommand,
  UpdateItemCommand,
} = require("@aws-sdk/client-dynamodb");
const {
  S3Client,
  GetObjectCommand,
  PutObjectCommand,
} = require("@aws-sdk/client-s3");
const { SQSClient, SendMessageCommand } = require("@aws-sdk/client-sqs");

const clientOptions = { maxAttempts: 3 };
const s3 = new S3Client(clientOptions);
const dynamo = new DynamoDBClient(clientOptions);
const sqs = new SQSClient(clientOptions);
const hash = (value) => createHash("sha256").update(value).digest("hex");

function configuration(serverDistDir = join(process.cwd(), ".next/server")) {
  const prefix = process.env.CACHE_KEY_PREFIX;
  const bucket = process.env.CACHE_BUCKET_NAME;
  const table = process.env.CACHE_TABLE_NAME;
  if (!prefix || !bucket || !table)
    throw new Error("Shared cache configuration is incomplete");
  const buildId =
    process.env.CACHE_BUILD_ID ||
    (process.env.NODE_ENV === "development"
      ? "development"
      : readFileSync(join(serverDistDir, "../BUILD_ID"), "utf8").trim());
  return { prefix, bucket, table, buildId, namespace: `${prefix}/${buildId}` };
}

function objectKey(config, key) {
  // Preserve the identity of the complete opaque Next key, not an inferred pathname.
  return `${config.namespace}/${hash(key)}.cache`;
}

function tagKey(config, tag) {
  // Tags intentionally span builds; a rollback must not resurrect invalidated content.
  return `${config.prefix}#tag#${hash(tag)}`;
}

async function invalidated(config, tags, lastModified) {
  // Strongly consistent reads avoid a stale local tag manifest on warm instances.
  const results = await Promise.all(
    [...new Set(tags)].map(async (tag) => {
      const result = await dynamo.send(
        new GetItemCommand({
          TableName: config.table,
          Key: { pk: { S: tagKey(config, tag) } },
          ConsistentRead: true,
          ProjectionExpression: "invalidatedAt",
        }),
      );
      return Number(result.Item?.invalidatedAt?.N || 0) >= lastModified;
    }),
  );
  return results.some(Boolean);
}

async function invalidateTags(config, tags, timestamp = Date.now()) {
  for (const tag of new Set(tags)) {
    try {
      await dynamo.send(
        new UpdateItemCommand({
          TableName: config.table,
          Key: { pk: { S: tagKey(config, tag) } },
          UpdateExpression: "SET invalidatedAt = :timestamp",
          ConditionExpression:
            "attribute_not_exists(invalidatedAt) OR invalidatedAt < :timestamp",
          ExpressionAttributeValues: { ":timestamp": { N: String(timestamp) } },
        }),
      );
    } catch (error) {
      if (error.name !== "ConditionalCheckFailedException") throw error;
    }
  }
}

async function enqueue(config, tags) {
  if (!process.env.CACHE_REVALIDATION_QUEUE_URL)
    throw new Error("Missing revalidation queue URL");
  const invalidatedAt = Date.now();
  // Next supplies the tags, including those generated by revalidatePath().
  // Treat them as opaque identifiers; no path/header interpretation is needed.
  for (const tag of new Set(tags)) {
    await sqs.send(
      new SendMessageCommand({
        QueueUrl: process.env.CACHE_REVALIDATION_QUEUE_URL,
        MessageBody: JSON.stringify({ tag, invalidatedAt }),
        MessageGroupId: hash(`${config.prefix}:${tag}`),
        MessageDeduplicationId: randomUUID(),
      }),
    );
  }
}

module.exports = {
  configuration,
  objectKey,
  invalidated,
  invalidateTags,
  enqueue,
  hash,
  s3,
  dynamo,
  sqs,
  GetObjectCommand,
  PutObjectCommand,
  UpdateItemCommand,
};
